// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.vision.documentimport timber.log.Timberimport com.roshan.persona.vision.barcode.RegionalQrFormatimport com.roshan.persona.vision.core.ConfidenceTierimport com.roshan.persona.vision.core.ConfidenceTieredResultimport com.roshan.persona.vision.ocr.DocumentTypeimport com.roshan.persona.vision.ocr.OcrEngineimport com.roshan.persona.vision.ocr.OcrOptionsimport com.roshan.persona.vision.ocr.OcrResultimport com.roshan.persona.vision.ocr.RgbImageimport com.roshan.persona.vision.ocr.TieredOcrResultimport kotlinx.coroutines.CoroutineDispatcherimport kotlinx.coroutines.withContext/** * NOUS — Document Scanner Engine (Module 6 v4 — Step 6.5, MAIN ORCHESTRATOR). * * The single entry point for document scanning — combines: *  - [EdgeDetector] — OpenCV edge detection + perspective correction *  - [OcrEngine] — ML Kit text recognition + field extraction *  - [UnifiedDocumentParser] — structured document parsing (receipt, prescription, ID, etc.) * * ## Pipeline (per strategy v4 §"Architecture → DocumentScannerEngine") * * ``` * Raw image (12 MP) → *   ↓ * 1. EdgeDetector.scanDocument(image) → ScannedDocument *    - Canny edge detection + 4-corner polygon *    - Perspective warp to bird's-eye (1280×720) *    - Adaptive threshold + CLAHE enhancement *    (150 ms budget) *   ↓ * 2. OcrEngine.recognize(scannedImage) → TieredOcrResult *    - ML Kit text recognition (60+ scripts) *    - Field extraction (PAN, Aadhaar, GSTIN, IFSC, UPI, phone, email) *    - Document type detection *    (500-800 ms budget) *   ↓ * 3. UnifiedDocumentParser.parse(documentType, fullText, fields) → StructuredDocument *    - Receipt / Prescription / BusinessCard / Aadhaar / PAN / Invoice / HandwrittenNote *    (50-100 ms budget) *   ↓ * 4. Return DocumentScanResult (ScannedDocument + OcrResult + StructuredDocument) * ``` * * Total budget: < 1.5 seconds for a typical receipt. * * ## Privacy (per strategy v4 §"Privacy & Security") * *  - **Government IDs require explicit per-scan consent.** *    If [DocumentScanOptions.explicitGovIdConsentGranted] is false, Aadhaar/PAN *    parsing is skipped (returns null structuredDocument). *  - Raw image is cryptographically shredded (DoD 5220.22-M 3-pass) within 60s *    of the scan (caller's responsibility — enforced by [DocumentScanOptions]). *  - Masked [com.roshan.persona.vision.ocr.GovernmentId] stored in encrypted Memory. * * ## Testability * * All native dependencies are injected: *  - [EdgeDetector] wraps OpenCV (via [EdgeDetectorDelegate]) *  - [OcrEngine] wraps ML Kit (via [OcrRecognizer] + [ImageProcessor]) *  - [UnifiedDocumentParser] is pure Kotlin (no Android deps) * * @see <a href="docs/strategy/module-6-vision-strategy-v4.md">§Step 6.5: DocumentScannerEngine</a> */class DocumentScannerEngine(    private val edgeDetector: EdgeDetector,    private val ocrEngine: OcrEngine,    private val documentParser: UnifiedDocumentParser,    private val dispatcher: CoroutineDispatcher,) {    /**     * Scan a document from a raw image.     *     * @param image the raw input image (RGB).     * @param options scan options (enhancement mode, consent, etc.).     * @return tiered document scan result.     */    suspend fun scanDocument(        image: RgbImage,        options: DocumentScanOptions = DocumentScanOptions.DEFAULT,    ): TieredDocumentScanResult = withContext(dispatcher) {        val startTime = System.currentTimeMillis()        Timber.tag(TAG).i("Document scan start: ${image.width}x${image.height}, options=$options.")        // 1. Edge detection + perspective correction + enhancement.        val scannedDoc = if (options.enableEdgeDetection) {            edgeDetector.scanDocument(image)        } else {            Timber.tag(TAG).d("Edge detection disabled — using original image.")            ScannedDocument(                image = image,                cornersDetected = false,                corners = null,                processingTimeMs = 0,            )        }        // 2. OCR on the (perspective-corrected + enhanced) image.        val ocrResult: TieredOcrResult = ocrEngine.recognize(            imageBytes = scannedDoc.image.pixels,  // Pass the corrected image bytes.            options = OcrOptions(                skipCache = options.skipOcrCache,                enhancementMode = options.ocrEnhancementMode,            ),        )        // 3. Parse structured document (if OCR succeeded).        val ocrValue = ocrResult.value        val structuredDoc = if (ocrResult.isUsable && ocrValue != null) {            documentParser.parse(                documentType = ocrValue.detectedDocumentType,                fullText = ocrValue.fullText,                extractedFields = ocrValue.extractedFields,                blocks = ocrValue.blocks,                explicitGovIdConsent = options.explicitGovIdConsentGranted,            )        } else {            Timber.tag(TAG).w("OCR not usable (tier=${ocrResult.tier}) — skipping structured parse.")            null        }        // 4. Build the combined result.        val elapsedMs = System.currentTimeMillis() - startTime        val result = DocumentScanResult(            scannedDocument = scannedDoc,            ocrResult = ocrResult.value,            structuredDocument = structuredDoc,            detectedDocumentType = ocrResult.value?.detectedDocumentType ?: DocumentType.UNKNOWN,            processingTimeMs = elapsedMs,            overallConfidence = ocrResult.confidence,        )        Timber.tag(TAG).i("Document scan complete: type=${result.detectedDocumentType}, " +            "structured=${structuredDoc != null}, ${elapsedMs}ms.")        ConfidenceTieredResult.from(result, result.overallConfidence)    }    /**     * Quick scan — skip edge detection (faster, for clean scans).     */    suspend fun quickScan(image: RgbImage): TieredDocumentScanResult = withContext(dispatcher) {        scanDocument(image, DocumentScanOptions.QUICK)    }    private companion object {        private const val TAG = "DocumentScanner"    }}// ──────────────────────────────────────────────────────────────────────────/** Combined result of document scanning. */data class DocumentScanResult(    val scannedDocument: ScannedDocument,    val ocrResult: OcrResult?,    val structuredDocument: com.roshan.persona.vision.ocr.StructuredDocument?,    val detectedDocumentType: DocumentType,    val processingTimeMs: Long,    val overallConfidence: Float,) {    /** True if a structured document was successfully parsed. */    val hasStructuredDoc: Boolean get() = structuredDocument != null    /** True if the document was identified as a government ID. */    val isGovernmentId: Boolean        get() = detectedDocumentType == DocumentType.AADHAAR_CARD ||                detectedDocumentType == DocumentType.PAN_CARD    /** Human-readable summary (for TTS readout). */    val summary: String        get() = structuredDocument?.summary            ?: ocrResult?.fullText?.take(100)            ?: "No text recognized."}/** Tiered document scan result. */typealias TieredDocumentScanResult = ConfidenceTieredResult<DocumentScanResult>// ──────────────────────────────────────────────────────────────────────────/** Document scan options. */data class DocumentScanOptions(    val enableEdgeDetection: Boolean = true,    val skipOcrCache: Boolean = false,    val ocrEnhancementMode: com.roshan.persona.vision.ocr.EnhancementMode = com.roshan.persona.vision.ocr.EnhancementMode.AUTO,    val explicitGovIdConsentGranted: Boolean = false,    val region: RegionalQrFormat = RegionalQrFormat.INDIA,) {    companion object {        /** Default — full pipeline with edge detection. */        val DEFAULT = DocumentScanOptions()        /** Quick — skip edge detection (for clean scans where speed matters). */        val QUICK = DocumentScanOptions(            enableEdgeDetection = false,            ocrEnhancementMode = com.roshan.persona.vision.ocr.EnhancementMode.NEVER,        )        /** Government ID scan — requires explicit consent. */        fun governmentIdScan(consentGranted: Boolean) = DocumentScanOptions(            enableEdgeDetection = true,            ocrEnhancementMode = com.roshan.persona.vision.ocr.EnhancementMode.ALWAYS,  // Force enhancement            explicitGovIdConsentGranted = consentGranted,        )    }}
